import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

maxpool2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>

__global__ void maxpool2d_forward_kernel(
    const float* input,
    float* output,
    int batch_size,
    int channels,
    int in_height,
    int in_width,
    int kernel_size,
    int stride,
    int padding,
    int dilation,
    int pooled_height,
    int pooled_width
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * channels * pooled_height * pooled_width;
    if (idx >= total_elements) return;

    int n = idx / (channels * pooled_height * pooled_width);
    int c = (idx / (pooled_height * pooled_width)) % channels;
    int ph = (idx / pooled_width) % pooled_height;
    int pw = idx % pooled_width;

    int h_start = ph * stride - padding;
    int w_start = pw * stride - padding;

    float max_val = -FLT_MAX;

    for (int kh = 0; kh < kernel_size; ++kh) {
        for (int kw = 0; kw < kernel_size; ++kw) {
            int h_in = h_start + kh * dilation;
            int w_in = w_start + kw * dilation;

            if (h_in >= 0 && h_in < in_height && w_in >= 0 && w_in < in_width) {
                int input_idx = n * channels * in_height * in_width +
                                c * in_height * in_width +
                                h_in * in_width +
                                w_in;
                float val = input[input_idx];
                max_val = max(max_val, val);
            }
        }
    }

    int output_idx = n * channels * pooled_height * pooled_width +
                     c * pooled_height * pooled_width +
                     ph * pooled_width +
                     pw;
    output[output_idx] = max_val;
}

torch::Tensor maxpool2d_cuda(torch::Tensor input, int kernel_size, int stride, int padding, int dilation) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(input.dim() == 4, "input must be 4D (N, C, H, W)");

    int batch_size = input.size(0);
    int channels = input.size(1);
    int in_height = input.size(2);
    int in_width = input.size(3);

    int pooled_height = (in_height + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int pooled_width = (in_width + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;

    auto output = torch::zeros({batch_size, channels, pooled_height, pooled_width}, input.options());

    int total_elements = output.numel();
    const int threads_per_block = 256;
    int num_blocks = (total_elements + threads_per_block - 1) / threads_per_block;

    maxpool2d_forward_kernel<<<num_blocks, threads_per_block>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        in_height,
        in_width,
        kernel_size,
        stride,
        padding,
        dilation,
        pooled_height,
        pooled_width
    );

    return output;
}
"""

maxpool2d_cpp_source = "torch::Tensor maxpool2d_cuda(torch::Tensor input, int kernel_size, int stride, int padding, int dilation);"

maxpool2d = load_inline(
    name='maxpool2d',
    cpp_sources=maxpool2d_cpp_source,
    cuda_sources=maxpool2d_source,
    functions=['maxpool2d_cuda'],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, kernel_size: int, stride: int, padding: int, dilation: int):
        super().__init__()
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return maxpool2d.maxpool2d_cuda(x, self.kernel_size, self.stride, self.padding, self.dilation)
